INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l41',2,6,41,'Do you call that a hat?','你把那个叫帽子吗?','must / have to / need / needn''t / mustn''t 的用法(KS17)主考——need 需要、must/have to 必须、needn''t 不必(=don''t have to)、mustn''t 禁止;needn''t 与 mustn''t 对比、needn''t have done(本来不必却做了);regret doing、remind sb of sth、remark/observe/notice 辨析(辅考·课文/难点①类)','帽店里,妻子对着镜子试帽子试了半个小时。丈夫坐在满是网眼的新式椅子上等得不耐烦,突然说“我们不应该买我们不需要的东西”,话一出口就后悔了。妻子回敬说“你没必要这么说”,还提醒他别忘了昨天买的那条难看透了的领带。丈夫说“我觉得它好看,男人有多少领带也不嫌多”,妻子答“女人有多少帽子也不嫌多”。10 分钟后,两人一道走出商店,妻子戴着一顶像灯塔一样的帽子。','{"q":"Listen and answer — What kind of shopping does the writer enjoy, do you think?","options":["He doesn''t seem to enjoy shopping for hats with his wife","He loves buying hats","He enjoys long shopping trips","He likes buying ties for his wife"],"answer_index":0}'::jsonb,'{"title":"must / have to / need / needn''t / mustn''t:需要、必须、不必、不许","intro":"need 表''需要''(I need a hat);must / have to 表''必须、不得不''(I must go);needn''t 表''不必''(= don''t have to);mustn''t 表''不许、禁止''。最容易混的是 mustn''t(禁止)和 needn''t(不必)——一个是不许做,一个是可做可不做。全用本课句子举例。","table":{"headers":["说法","意思"],"rows":[["I need a new hat.","我需要一顶新帽子(need = 需要)"],["I must buy one. / I have to buy one.","我必须买一顶(must / have to = 必须)"],["You needn''t wait for me. = You don''t have to wait.","你不必等我(needn''t = 不必)"],["You mustn''t smoke here. It is forbidden.","这儿不许抽烟(mustn''t = 禁止)"],["You needn''t have said that.","你本来用不着说那话(却说了)"]]},"specialRules":[{"rule":"mustn''t = 不许、禁止(No!);needn''t = 不必、没必要(可做可不做)。别混:You mustn''t smoke(禁止)≠ You needn''t smoke(不必)。","mark":"mustn''t 禁止 ≠ needn''t 不必"},{"rule":"needn''t have done 表示''本来用不着做,却已经做了'':You needn''t have waited for me(你本来不必等,却等了)。","mark":"needn''t have done"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l41',1,NULL,'''Do you call that a hat?'' I said to my wife.','“你把那个叫帽子吗?”我对妻子说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l41',2,NULL,'''You needn''t be so rude about it,'' my wife answered as she looked at herself in the mirror.','“你说话没必要这样不客气,”妻子边照镜子边回答。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l41',3,NULL,'I sat down on one of those modern chairs with holes in it and waited.','我坐在一把满是网眼的新式椅子上等着。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l41',4,NULL,'We had been in the hat shop for half an hour and my wife was still in front of the mirror.','我们在这家帽店已经呆了半个小时,妻子仍站在镜子前。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l41',5,NULL,'''We mustn''t buy things we don''t need,'' I remarked suddenly. I regretted saying it almost at once.','“我们不该买不需要的东西,”我突然评论道,话一出口几乎立刻就后悔了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l41',6,NULL,'''You needn''t have said that,'' my wife answered. ''I needn''t remind you of that terrible tie you bought yesterday.''','“你本来用不着这么说,”妻子回答,“我也不必提醒你昨天买的那条难看透了的领带。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l41',7,NULL,'''I find it beautiful,'' I said. ''A man can never have too many ties.''','“我觉得它好看,”我说,“男人有多少领带也不嫌多。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l41',8,NULL,'''And a woman can''t have too many hats,'' she answered.','“女人有多少帽子也不嫌多。”她回答。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l41',9,NULL,'Ten minutes later we walked out of the shop together. My wife was wearing a hat that looked like a lighthouse!','10 分钟后我们一道走出商店,妻子戴着一顶像灯塔一样的帽子!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
